import{_ as n,a as r,b as h,c as w}from"./chunks/1UaCNTjpnJE-1280.F1Px3f_M.js";import{_ as p,C as o,o as c,c as u,j as e,a,E as s,a8 as d}from"./chunks/framework.27XeWUA0.js";const N=JSON.parse('{"title":"AI Digest · Sat 14 Nov 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"index","routine":"digest"},"relativePath":"digest/index.md","filePath":"digest/[date].md"}'),m={name:"digest/index.md"},f=n+" 640w, "+h+" 1280w",g=r+" 640w, "+w+" 1280w",b={id:"ai-digest-·-sat-14-nov-2026",tabindex:"-1"};function v(k,t,y,A,_,S){const i=o("Badge"),l=o("DayFilter");return c(),u("div",null,[e("h1",b,[t[0]||(t[0]=a("AI Digest · Sat 14 Nov 2026 ",-1)),s(i,{type:"tip",text:"2"}),t[1]||(t[1]=a()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#ai-digest-·-sat-14-nov-2026","aria-label":'Permalink to "AI Digest · Sat 14 Nov 2026 <Badge type="tip" text="2" />"'},"​",-1))]),t[3]||(t[3]=e("p",{class:"sub"},"AI Engineer + Better Stack daily digest — 14 Nov 2026 · run date Sat 14 Nov 2026 · 2 videos",-1)),t[4]||(t[4]=e("div",{class:"overview"},[e("p",null,[e("strong",null,"AI Engineer:"),a(" no new talks in the last 24 hours.")]),e("p",null,[e("strong",null,"Better Stack:"),a(" 2 new videos. The newest is podcast Ep. 20 with TanStack creator Tanner Linsley (13 Nov, 6:30 PM IST). It touches covered ground (JS ecosystem, supply-chain security, slop forks), but the fresh part is why he pulled React Server Components out of tanstack.com. Also new: a short explainer on Go 1.27's new JSON library (13 Nov, 5:45 PM IST). Neither is mostly a repeat.")])],-1)),s(l),t[5]||(t[5]=d('<div class="grid cards2"><article class="it full" id="v-AoV5ufWAf7w" data-title="React Server Components Weren&#39;t Worth It | Better Stack Podcast Ep. 20" data-channel="Better Stack" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=AoV5ufWAf7w" target="_blank" rel="noopener"><img src="'+n+'" srcset="'+f+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=AoV5ufWAf7w" target="_blank" rel="noopener">React Server Components Weren&#39;t Worth It | Better Stack Podcast Ep. 20</a></h3><div class="meta">Better Stack · Tanner Linsley (creator of TanStack) with hosts James and Andrew · uploaded 13 Nov, 6:30 PM IST · 1:39:37</div><div class="verdict v-worth"><b>Verdict:</b> worth watching from 58:44 — the RSC teardown with real numbers is the fresh part; skim the Lovable/Claude story (42:18) and npm hack (1:25:03), and skip the origin story.</div><div class="repeat">🔁 Repeat: &#39;JS/TS ecosystem&#39; — seen 15 times before. New here: the first long interview with TanStack&#39;s creator, including why he pulled React Server Components out of tanstack.com.</div><div class="repeat">🔁 Repeat: &#39;AI supply chain security&#39; — seen 8 times before. New here: a first-person account of how TanStack handled its npm hack (war room, postmortem), not another general security talk.</div><div class="repeat">🔁 Repeat: &#39;software cloning&#39; — seen 4 times before. New here: Tanner&#39;s own &quot;slop fork&quot; of React (Redact) and where he draws the line between a slop fork and AI-assisted engineering.</div><div class="sh">Origins and money</div><ul><li><strong>Built at Nozzle:</strong> TanStack came out of Nozzle, an SEO data startup that tracked custom lists of 100,000+ keywords on Google; React Table was built there as the data grid, and React Query came after 3–4 years of struggling to scale Redux (<a href="https://www.youtube.com/watch?v=AoV5ufWAf7w&amp;t=74s" target="_blank" rel="noopener">1:14</a>–<a href="https://www.youtube.com/watch?v=AoV5ufWAf7w&amp;t=269s" target="_blank" rel="noopener">4:29</a>, <a href="https://www.youtube.com/watch?v=AoV5ufWAf7w&amp;t=793s" target="_blank" rel="noopener">13:13</a>–<a href="https://www.youtube.com/watch?v=AoV5ufWAf7w&amp;t=810s" target="_blank" rel="noopener">13:30</a>)</li><li><strong>No VC on purpose:</strong> Investors offered &quot;bags and bags of money&quot; in 2018, but he refused to build a hosting product; core maintainers keep full-time jobs elsewhere and get extra pay from TanStack&#39;s sponsorships and partnerships, and Tanner went full-time three years ago (<a href="https://www.youtube.com/watch?v=AoV5ufWAf7w&amp;t=2148s" target="_blank" rel="noopener">35:48</a>–<a href="https://www.youtube.com/watch?v=AoV5ufWAf7w&amp;t=2344s" target="_blank" rel="noopener">39:04</a>)</li></ul><div class="sh">AI, slop PRs and slop forks</div><ul><li><strong>PRs closed on some repos:</strong> TanStack shut off PRs on a couple of projects because of AI junk and cache-poisoning attempts after its security incident; he also brushed off someone&#39;s &quot;19 times faster&quot; Grok rewrite of TanStack Router (<a href="https://www.youtube.com/watch?v=AoV5ufWAf7w&amp;t=1188s" target="_blank" rel="noopener">19:48</a>–<a href="https://www.youtube.com/watch?v=AoV5ufWAf7w&amp;t=1290s" target="_blank" rel="noopener">21:30</a>)</li><li><strong>TanStack Charts and Redact:</strong> He designed the Charts API by hand but says &quot;huge swaths&quot; were implemented with AI in about two weeks; he also built Redact, an experimental React-compatible fork, in 2–3 days, and it runs tanstack.com today and saves about 30 KB of JavaScript, but he says don&#39;t use it (<a href="https://www.youtube.com/watch?v=AoV5ufWAf7w&amp;t=1290s" target="_blank" rel="noopener">21:30</a>–<a href="https://www.youtube.com/watch?v=AoV5ufWAf7w&amp;t=1453s" target="_blank" rel="noopener">24:13</a>)</li><li><strong>Code is cheap, hardening isn&#39;t:</strong> He says AI-run micro-benchmarks (like a &quot;10x faster&quot; link that saves nanoseconds) mislead, and that mass slop-forking would &quot;destroy open source&quot;; small helper packages like left-pad are gone, but big libraries matter more now (<a href="https://www.youtube.com/watch?v=AoV5ufWAf7w&amp;t=1500s" target="_blank" rel="noopener">25:00</a>–<a href="https://www.youtube.com/watch?v=AoV5ufWAf7w&amp;t=1800s" target="_blank" rel="noopener">30:00</a>)</li></ul><div class="sh">Lovable, Claude and adoption</div><ul><li><strong>Lovable and Claude switched:</strong> Lovable tried four frameworks, picked TanStack Start for all generated apps, and moved lovable.dev itself onto it; Anthropic moved the Claude web app to TanStack without telling the team, and they found out from a tweet (<a href="https://www.youtube.com/watch?v=AoV5ufWAf7w&amp;t=2538s" target="_blank" rel="noopener">42:18</a>–<a href="https://www.youtube.com/watch?v=AoV5ufWAf7w&amp;t=2760s" target="_blank" rel="noopener">46:00</a>)</li><li><strong>Less training data helps:</strong> Lovable found models couldn&#39;t stick to one Next.js version because of mixed training data, while TanStack Start has only one way of doing things, so a single instruction is enough (<a href="https://www.youtube.com/watch?v=AoV5ufWAf7w&amp;t=3180s" target="_blank" rel="noopener">53:00</a>–<a href="https://www.youtube.com/watch?v=AoV5ufWAf7w&amp;t=3300s" target="_blank" rel="noopener">55:00</a>)</li><li><strong>npm stats and 1.0:</strong> By his npm stats, TanStack Query is used about as much as Next.js, with a jump in 2026 he puts down mostly to Lovable; Start 1.0 has one middleware checkbox left, and TanStack AI hit release candidate the day they recorded (<a href="https://www.youtube.com/watch?v=AoV5ufWAf7w&amp;t=2850s" target="_blank" rel="noopener">47:30</a>–<a href="https://www.youtube.com/watch?v=AoV5ufWAf7w&amp;t=2960s" target="_blank" rel="noopener">49:20</a>, <a href="https://www.youtube.com/watch?v=AoV5ufWAf7w&amp;t=3039s" target="_blank" rel="noopener">50:39</a>–<a href="https://www.youtube.com/watch?v=AoV5ufWAf7w&amp;t=3140s" target="_blank" rel="noopener">52:20</a>)</li></ul><div class="sh">Why RSC came out</div><ul><li><strong>Extra complexity:</strong> Moving the docs&#39; Markdown pipeline into RSC meant a separate React module graph and Vite tricks to stop bundles leaking into each other, and every later feature had to handle RSC edge cases (<a href="https://www.youtube.com/watch?v=AoV5ufWAf7w&amp;t=3524s" target="_blank" rel="noopener">58:44</a>–<a href="https://www.youtube.com/watch?v=AoV5ufWAf7w&amp;t=3840s" target="_blank" rel="noopener">1:04:00</a>)</li><li><strong>16 KB beat RSC:</strong> RSC only kept Shiki and Rehype off the client, so he had AI check how much of the Markdown spec the docs actually used (about 60%) and write custom libraries; the result cost 16 KB in total, and shipping that beat RSC&#39;s HTML payload, which became TanStack Markdown and Highlight (<a href="https://www.youtube.com/watch?v=AoV5ufWAf7w&amp;t=3939s" target="_blank" rel="noopener">1:05:39</a>–<a href="https://www.youtube.com/watch?v=AoV5ufWAf7w&amp;t=4330s" target="_blank" rel="noopener">1:12:10</a>)</li><li><strong>Verdict on RSC:</strong> He calls the ROI on RSC poor: &quot;I don&#39;t think it was worth it&quot; (<a href="https://www.youtube.com/watch?v=AoV5ufWAf7w&amp;t=4790s" target="_blank" rel="noopener">1:19:50</a>–<a href="https://www.youtube.com/watch?v=AoV5ufWAf7w&amp;t=4830s" target="_blank" rel="noopener">1:20:30</a>)</li></ul><div class="sh">The npm hack</div><ul><li><strong>Response:</strong> He was on vacation when it hit; about 15 maintainers were in a war room within 10–15 minutes, the first bad packages were deprecated within minutes, and security firms called it the fastest response they had seen. The postmortem was published for other libraries to follow (<a href="https://www.youtube.com/watch?v=AoV5ufWAf7w&amp;t=5103s" target="_blank" rel="noopener">1:25:03</a>–<a href="https://www.youtube.com/watch?v=AoV5ufWAf7w&amp;t=5560s" target="_blank" rel="noopener">1:32:40</a>)</li></ul></div></article><article class="it full" id="v-1UaCNTjpnJE" data-title="Go Rewrote JSON After 15 Years... Here&#39;s What Changed." data-channel="Better Stack" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=1UaCNTjpnJE" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+g+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=1UaCNTjpnJE" target="_blank" rel="noopener">Go Rewrote JSON After 15 Years... Here&#39;s What Changed.</a></h3><div class="meta">Better Stack · Josh (Better Stack) · uploaded 13 Nov, 5:45 PM IST · 9:03</div><div class="verdict v-worth"><b>Verdict:</b> worth watching if you write Go APIs — a short, concrete rundown of the breaking changes; otherwise skip.</div><div class="sh">What changed in encoding/json/v2</div><ul><li><strong>Nil slices and maps:</strong> v1 turns nil slices and maps into `null`, which breaks frontends that call `.map`; v2 gives `[]` and `{}` without any code changes, and an option keeps the old behaviour (<a href="https://www.youtube.com/watch?v=1UaCNTjpnJE&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=1UaCNTjpnJE&amp;t=45s" target="_blank" rel="noopener">0:45</a>, <a href="https://www.youtube.com/watch?v=1UaCNTjpnJE&amp;t=97s" target="_blank" rel="noopener">1:37</a>–<a href="https://www.youtube.com/watch?v=1UaCNTjpnJE&amp;t=163s" target="_blank" rel="noopener">2:43</a>)</li><li><strong>Duplicate keys rejected:</strong> Given `&quot;role&quot;:&quot;user&quot;` and `&quot;role&quot;:&quot;admin&quot;`, v1 silently takes &quot;admin&quot;; v2 throws an error. He calls this a security fix, because services that pick different values can disagree on permissions. Invalid UTF-8 is also rejected now (<a href="https://www.youtube.com/watch?v=1UaCNTjpnJE&amp;t=163s" target="_blank" rel="noopener">2:43</a>–<a href="https://www.youtube.com/watch?v=1UaCNTjpnJE&amp;t=217s" target="_blank" rel="noopener">3:37</a>)</li><li><strong>Case-sensitive fields:</strong> v2 matches struct fields case-sensitively by default, so clients sending the wrong casing can silently stop filling a field; unknown fields are still ignored unless you set `RejectUnknownMembers` (<a href="https://www.youtube.com/watch?v=1UaCNTjpnJE&amp;t=217s" target="_blank" rel="noopener">3:37</a>–<a href="https://www.youtube.com/watch?v=1UaCNTjpnJE&amp;t=252s" target="_blank" rel="noopener">4:12</a>)</li></ul><div class="sh">Performance and design</div><ul><li><strong>Faster even on v1:</strong> Official benchmarks show up to 10x faster unmarshalling, and Go 1.27 moved the old `encoding/json` onto the new engine, so you get some of the speed just by upgrading. Marshalling is about the same (<a href="https://www.youtube.com/watch?v=1UaCNTjpnJE&amp;t=252s" target="_blank" rel="noopener">4:12</a>–<a href="https://www.youtube.com/watch?v=1UaCNTjpnJE&amp;t=299s" target="_blank" rel="noopener">4:59</a>, <a href="https://www.youtube.com/watch?v=1UaCNTjpnJE&amp;t=405s" target="_blank" rel="noopener">6:45</a>–<a href="https://www.youtube.com/watch?v=1UaCNTjpnJE&amp;t=433s" target="_blank" rel="noopener">7:13</a>)</li><li><strong>Two layers:</strong> `jsontext` handles syntax, tokens and streaming, and `json/v2` maps to Go values, with new `MarshalWrite` / `UnmarshalRead` and per-call options (<a href="https://www.youtube.com/watch?v=1UaCNTjpnJE&amp;t=299s" target="_blank" rel="noopener">4:59</a>–<a href="https://www.youtube.com/watch?v=1UaCNTjpnJE&amp;t=332s" target="_blank" rel="noopener">5:32</a>)</li><li><strong>vs Sonic and friends:</strong> Sonic (JIT + SIMD), go-json and json-iterator can still beat v2 on some workloads; if you&#39;re on Sonic and it&#39;s faster, keep it, but benchmark v2 for new projects before adding a dependency (<a href="https://www.youtube.com/watch?v=1UaCNTjpnJE&amp;t=332s" target="_blank" rel="noopener">5:32</a>–<a href="https://www.youtube.com/watch?v=1UaCNTjpnJE&amp;t=380s" target="_blank" rel="noopener">6:20</a>)</li></ul><div class="sh">Migrating</div><ul><li><strong>Gotchas:</strong> `omitempty` behaves differently, map keys are no longer sorted (exact-output tests may fail), and `time.Duration` has no default format, so you get an error until you choose one (<a href="https://www.youtube.com/watch?v=1UaCNTjpnJE&amp;t=380s" target="_blank" rel="noopener">6:20</a>–<a href="https://www.youtube.com/watch?v=1UaCNTjpnJE&amp;t=433s" target="_blank" rel="noopener">7:13</a>)</li><li><strong>Path:</strong> Upgrade to 1.27 first, then move endpoints one at a time, starting from `DefaultOptionsV1`; the `jsonsplit` tool runs v1 and v2 side by side, reports the differences but still returns v1&#39;s result, and can sample only some calls (<a href="https://www.youtube.com/watch?v=1UaCNTjpnJE&amp;t=433s" target="_blank" rel="noopener">7:13</a>–<a href="https://www.youtube.com/watch?v=1UaCNTjpnJE&amp;t=542s" target="_blank" rel="noopener">9:02</a>)</li></ul></div></article></div>',1))])}const V=p(m,[["render",v]]);export{N as __pageData,V as default};
